import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:vestra/core/database/app_database.dart';

import 'generated/schema.dart';
import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v2.dart' as v2;

/// Generated by `dart run drift_dev make-migrations`, then filled in.
/// Every schema version must migrate to every later one without data loss.
void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() => verifier = SchemaVerifier(GeneratedHelper()));

  group('schema migrations', () {
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      for (final toVersion in versions.skip(i + 1)) {
        test(
          'v$fromVersion -> v$toVersion matches the declared schema',
          () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = AppDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          },
        );
      }
    }
  });

  test('v1 -> v2 keeps portfolio, prices and settings', () async {
    // Raw schema classes store DateTime as unix seconds.
    final created = DateTime(2026, 1, 2).millisecondsSinceEpoch ~/ 1000;
    await verifier.testWithDataIntegrity(
      oldVersion: 1,
      newVersion: 2,
      createOld: v1.DatabaseAtV1.new,
      createNew: v2.DatabaseAtV2.new,
      openTestedDatabase: AppDatabase.new,
      createItems: (batch, oldDb) {
        batch
          ..insert(
            oldDb.assets,
            v1.AssetsData(
              id: 1,
              type: 'currency',
              code: 'USD',
              name: 'Amerikan Doları',
              createdAt: created,
            ),
          )
          ..insert(
            oldDb.assetTransactions,
            v1.AssetTransactionsData(
              id: 1,
              assetId: 1,
              kind: 'buy',
              quantity: '100.5',
              unitPriceTry: '41.25',
              date: created,
              createdAt: created,
            ),
          )
          ..insert(
            oldDb.priceCache,
            v1.PriceCacheData(
              type: 'currency',
              code: 'USD',
              priceTry: '42.1',
              source: 'frankfurter',
              fetchedAt: created,
            ),
          )
          ..insert(
            oldDb.appSettings,
            const v1.AppSettingsData(key: 'theme_preference', value: 'dark'),
          );
      },
      validateItems: (newDb) async {
        expect(await newDb.select(newDb.assets).get(), [
          v2.AssetsData(
            id: 1,
            type: 'currency',
            code: 'USD',
            name: 'Amerikan Doları',
            createdAt: created,
          ),
        ]);
        expect(
          (await newDb.select(newDb.assetTransactions).getSingle()).quantity,
          '100.5',
        );
        expect(await newDb.select(newDb.priceCache).get(), [
          v2.PriceCacheData(
            type: 'currency',
            code: 'USD',
            priceTry: '42.1',
            source: 'frankfurter',
            fetchedAt: created,
          ),
        ]);
        expect(
          (await newDb.select(newDb.appSettings).getSingle()).value,
          'dark',
        );
      },
    );
  });
}
